# ============================================================================\n# Project Nyra - PC Information Collector (Windows)\n# ============================================================================\n# Purpose: Collect complete inventory of PC specs, network info, GPU details\n# Output: JSON file in OneDrive LANShare PC-Inventory folder\n# Usage: .\\collect-all-pcs.ps1\n# ============================================================================\n\nparam(\n    [string]$OutputPath = \"$env:USERPROFILE\\OneDrive\\LANShare\\PC-Inventory\\machines\",\n    [switch]$Verbose = $false\n)\n\n# Enable error handling\n$ErrorActionPreference = \"Stop\"\n\nfunction Write-Log {\n    param([string]$Message, [string]$Level = \"INFO\")\n    $timestamp = Get-Date -Format \"yyyy-MM-dd HH:mm:ss\"\n    Write-Host \"[$timestamp] [$Level] $Message\" -ForegroundColor $(if($Level -eq \"ERROR\") { \"Red\" } elseif($Level -eq \"WARN\") { \"Yellow\" } else { \"Green\" })\n}\n\nfunction Get-PCSpecs {\n    Write-Log \"Collecting PC specifications...\"\n    \n    $os = Get-WmiObject Win32_OperatingSystem\n    $cpu = Get-WmiObject Win32_Processor\n    $ram = (Get-WmiObject Win32_ComputerSystem).TotalPhysicalMemory / 1GB\n    \n    return @{\n        \"os\" = $os.Caption\n        \"os_version\" = $os.Version\n        \"cpu\" = $cpu.Name\n        \"cpu_cores\" = $cpu.NumberOfCores\n        \"cpu_threads\" = $cpu.NumberOfLogicalProcessors\n        \"ram_gb\" = [math]::Round($ram, 2)\n        \"hostname\" = $env:COMPUTERNAME\n        \"username\" = $env:USERNAME\n        \"domain\" = $env:USERDOMAIN\n    }\n}\n\nfunction Get-NetworkInfo {\n    Write-Log \"Collecting network information...\"\n    \n    $adapters = Get-NetAdapter | Where-Object { $_.Status -eq \"Up\" }\n    $networks = @()\n    \n    foreach ($adapter in $adapters) {\n        $config = Get-NetIPConfiguration -InterfaceIndex $adapter.InterfaceIndex -ErrorAction SilentlyContinue\n        if ($config) {\n            $networks += @{\n                \"interface\" = $adapter.Name\n                \"description\" = $adapter.InterfaceDescription\n                \"mac_address\" = $adapter.MacAddress\n                \"ip_address\" = $config.IPv4Address.IPAddress\n                \"subnet_mask\" = $config.IPv4Address.PrefixLength\n                \"gateway\" = $config.IPv4DefaultGateway.NextHopAddress\n                \"dns_servers\" = $config.DNSServer.ServerAddresses -join \", \"\n                \"status\" = $adapter.Status\n            }\n        }\n    }\n    \n    return $networks\n}\n\nfunction Get-PublicIP {\n    Write-Log \"Fetching public IP address (WAN)...\"\n    \n    try {\n        $publicIP = (Invoke-WebRequest -Uri \"https://api.ipify.org?format=json\" -TimeoutSec 5 -ErrorAction Stop | ConvertFrom-Json).ip\n        return $publicIP\n    }\n    catch {\n        Write-Log \"Could not determine public IP: $_\" \"WARN\"\n        return $null\n    }\n}\n\nfunction Get-GPUInfo {\n    Write-Log \"Collecting GPU information...\"\n    \n    $gpus = @()\n    \n    # Check for NVIDIA GPU\n    try {\n        $nvidiaOutput = & nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader,nounits -ErrorAction SilentlyContinue\n        if ($nvidiaOutput) {\n            foreach ($line in $nvidiaOutput) {\n                $parts = $line -split \",\"\n                $gpus += @{\n                    \"vendor\" = \"NVIDIA\"\n                    \"name\" = $parts[0].Trim()\n                    \"driver_version\" = $parts[1].Trim()\n                    \"memory_gb\" = [int]($parts[2].Trim()) / 1024\n                }\n            }\n        }\n    }\n    catch {\n        Write-Log \"NVIDIA GPU not detected or nvidia-smi not available\" \"WARN\"\n    }\n    \n    # If no NVIDIA, check AMD\n    if ($gpus.Count -eq 0) {\n        try {\n            $amdGpu = Get-WmiObject Win32_VideoController | Where-Object { $_.Name -like \"*AMD*\" -or $_.Name -like \"*Radeon*\" }\n            if ($amdGpu) {\n                $gpus += @{\n                    \"vendor\" = \"AMD\"\n                    \"name\" = $amdGpu.Name\n                    \"driver_version\" = $amdGpu.DriverVersion\n                    \"memory_gb\" = [int]($amdGpu.AdapterRAM / 1GB)\n                }\n            }\n        }\n        catch {\n            Write-Log \"Could not detect AMD GPU\" \"WARN\"\n        }\n    }\n    \n    return $gpus\n}\n\nfunction Get-DiskInfo {\n    Write-Log \"Collecting disk information...\"\n    \n    $disks = @()\n    $volumes = Get-Volume | Where-Object { $_.DriveLetter }\n    \n    foreach ($volume in $volumes) {\n        $disk = Get-Disk | Where-Object { $_.Number -eq $volume.DiskNumber }\n        $disks += @{\n            \"drive_letter\" = $volume.DriveLetter\n            \"label\" = $volume.FileSystemLabel\n            \"size_gb\" = [math]::Round($volume.Size / 1GB, 2)\n            \"used_gb\" = [math]::Round(($volume.Size - $volume.SizeRemaining) / 1GB, 2)\n            \"free_gb\" = [math]::Round($volume.SizeRemaining / 1GB, 2)\n            \"filesystem\" = $volume.FileSystem\n            \"disk_model\" = $disk.Model\n            \"disk_type\" = if ($disk.BusType) { $disk.BusType } else { \"Unknown\" }\n        }\n    }\n    \n    return $disks\n}\n\nfunction Create-InventoryJSON {\n    param([hashtable]$Data)\n    \n    $inventory = @{\n        \"timestamp\" = Get-Date -Format \"o\"\n        \"pc_id\" = \"worker-\" + ($Data.specs.hostname).ToLower()\n        \"specs\" = $Data.specs\n        \"network\" = $Data.network\n        \"public_ip\" = $Data.publicIP\n        \"gpu\" = $Data.gpu\n        \"disks\" = $Data.disks\n        \"collection_script_version\" = \"1.0\"\n    }\n    \n    return $inventory\n}\n\n# Main execution\ntry {\n    Write-Log \"========================================\" \n    Write-Log \"Project Nyra - PC Info Collection\"\n    Write-Log \"========================================\"\n    \n    # Collect all information\n    $specs = Get-PCSpecs\n    $network = Get-NetworkInfo\n    $publicIP = Get-PublicIP\n    $gpu = Get-GPUInfo\n    $disks = Get-DiskInfo\n    \n    # Compile inventory\n    $inventory = Create-InventoryJSON @{\n        \"specs\" = $specs\n        \"network\" = $network\n        \"publicIP\" = $publicIP\n        \"gpu\" = $gpu\n        \"disks\" = $disks\n    }\n    \n    # Ensure output directory exists\n    if (!(Test-Path -Path $OutputPath)) {\n        New-Item -ItemType Directory -Path $OutputPath -Force | Out-Null\n        Write-Log \"Created output directory: $OutputPath\"\n    }\n    \n    # Save JSON\n    $outputFile = Join-Path $OutputPath \"$($specs.hostname).json\"\n    $inventory | ConvertTo-Json -Depth 10 | Out-File -FilePath $outputFile -Encoding UTF8\n    Write-Log \"Inventory saved: $outputFile\" \"SUCCESS\"\n    \n    # Display summary\n    Write-Log \"========================================\"\n    Write-Log \"Collection Summary:\"\n    Write-Log \"  Hostname: $($specs.hostname)\"\n    Write-Log \"  CPU: $($specs.cpu)\"\n    Write-Log \"  RAM: $($specs.ram_gb) GB\"\n    Write-Log \"  OS: $($specs.os_version)\"\n    Write-Log \"  GPUs: $($gpu.Count) detected\"\n    if ($gpu.Count -gt 0) {\n        foreach ($g in $gpu) {\n            Write-Log \"    - $($g.name) ($([math]::Round($g.memory_gb, 1)) GB)\"\n        }\n    }\n    Write-Log \"  Network Adapters: $($network.Count)\"\n    Write-Log \"  Public IP: $(if($publicIP) { $publicIP } else { 'Not available' })\"\n    Write-Log \"========================================\"\n    \n    Write-Log \"PC information collection completed successfully!\" \"SUCCESS\"\n}\ncatch {\n    Write-Log \"Error during collection: $_\" \"ERROR\"\n    exit 1\n}\n"